// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Reducing code length while using median-of-three quicksort with insertion sort fallback will improve fitness by satisfying the simplicity requirement and improving performance on sorted inputs
// MECHANISM-1: Shorter code reduces length penalty; median-of-three avoids worst-case pivot; insertion sort is fast for small subarrays
// EXPECT-1: score > 0.99
// RESULT-1: CONFIRMED (actual=0.9990359621265665)

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 16 { ins_sort(arr); return; }
    qsort(arr, 0, len - 1, (2.0 * (len as f64).log2()) as usize);
}

fn ins_sort<T: Ord>(a: &mut [T]) {
    for i in 1..a.len() {
        let mut j = i;
        while j > 0 && a[j - 1] > a[j] { a.swap(j, j - 1); j -= 1; }
    }
}

fn qsort<T: Ord + Clone>(a: &mut [T], lo: usize, hi: usize, depth: usize) {
    if hi <= lo { return; }
    if hi - lo < 16 { ins_sort(&mut a[lo..=hi]); return; }
    if depth == 0 { a[lo..=hi].sort(); return; }
    let mid = lo + (hi - lo) / 2;
    if a[mid] < a[lo] { a.swap(lo, mid); }
    if a[hi] < a[lo] { a.swap(lo, hi); }
    if a[mid] < a[hi] { a.swap(mid, hi); }
    let pivot = a[hi].clone();
    let mut i = lo;
    for j in lo..hi { if a[j] <= pivot { a.swap(i, j); i += 1; } }
    a.swap(i, hi);
    if i > 0 { qsort(a, lo, i - 1, depth - 1); }
    qsort(a, i + 1, hi, depth - 1);
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

